const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmtTime=s=>`${Math.floor(Math.max(0,s)/60)}:${String(Math.max(0,s)%60).padStart(2,'0')}`;
const fmtDur=s=>{s=Math.max(0,Math.round(Number(s)||0));const m=Math.floor(s/60),sec=s%60;return m>=60?`${Math.floor(m/60)}h ${m%60}m`:`${m}:${String(sec).padStart(2,'0')}`};
const initials=n=>String(n||'BS').trim().split(/\s+/).slice(0,2).map(x=>x[0]?.toUpperCase()).join('')||'BS';
const cache=()=>{try{return JSON.parse(localStorage.getItem(CACHE_KEY)||'{}')}catch{return{}}};
