const getQueue=()=>{try{return JSON.parse(localStorage.getItem(QUEUE_KEY)||'[]')}catch{return[]}};
const setQueue=q=>localStorage.setItem(QUEUE_KEY,JSON.stringify(q));
function toast(msg,error=false){toastEl.textContent=msg;toastEl.className=`show${error?' error':''}`;clearTimeout(toastEl._t);toastEl._t=setTimeout(()=>toastEl.className='',2800)}

async function api(action,payload={},options={}){
  const controller=new AbortController();
  const t=setTimeout(()=>controller.abort(),options.timeout||15000);
  try{
    const res=await fetch(API_URL,{method:'POST',headers:{'Content-Type':'application/json','apikey':API_KEY},body:JSON.stringify({action,...payload,...(S.token?{token:S.token}:{})}),signal:controller.signal});
    const data=await res.json().catch(()=>({error:'Invalid server response'}));
    if(!res.ok) throw Object.assign(new Error(data.error||`Request failed (${res.status})`),{status:res.status,data});
    return data;
  }finally{clearTimeout(t)}
}

function days(){return (S.plan?.plan_days||[]).slice().sort((a,b)=>a.sort_order-b.sort_order)}
function dayExercises(day){return (day?.plan_day_exercises||[]).slice().sort((a,b)=>a.sort_order-b.sort_order).map(slot=>({...slot,exercise:{...(slot.exercises||{}),...(S.exercises||[]).find(e=>e.id===slot.exercises?.id)}}))}
function allExercises(){const map=new Map();for(const d of days())for(const slot of dayExercises(d)){const e=slot.exercise;if(e?.id&&!map.has(e.id))map.set(e.id,{...e,slots:[slot]});else if(e?.id)map.get(e.id).slots.push(slot)}for(const e of S.exercises||[]){const old=map.get(e.id);map.set(e.id,{...old,...e,slots:old?.slots||[]});}return [...map.values()].sort((a,b)=>a.name.localeCompare(b.name))}
function dayById(id){return days().find(d=>d.id===id)||null}
function slotByExercise(day,exerciseId){return dayExercises(day).find(x=>x.exercise.id===exerciseId)||null}
function latestCompleted(){return S.history.find(h=>h.status==='completed')||null}
function nextDay(){const ds=days();if(!ds.length)return null;const last=latestCompleted();if(!last)return ds[0];const idx=ds.findIndex(d=>d.id===last.plan_day_id);return ds[(idx+1+ds.length)%ds.length]||ds[0]}
function selectedDay(){return dayById(S.selectedDayId)||nextDay()||days()[0]||null}
function activeSets(){return S.active?.sets||[]}
function setsFor(exId){return activeSets().filter(x=>x.exercise_id===exId).sort((a,b)=>a.set_number-b.set_number)}
function previousSets(exId){for(const h of S.history){if(h.status!=='completed')continue;const xs=(h.sets||[]).filter(x=>x.exercise_id===exId&&x.completion_status==='completed').sort((a,b)=>a.set_number-b.set_number);if(xs.length)return xs.map(x=>({...x,weight:x.weight==null?null:Math.round(Number(x.weight)*((x.units||'lb')===S.user.units?1:S.user.units==='kg'?1/2.2046226218:2.2046226218)*100)/100}))}return[]}
function activeProgress(){if(!S.activeDay)return{logged:0,planned:0,pct:0};const slots=dayExercises(S.activeDay);const planned=slots.reduce((n,s)=>n+s.target_sets,0);const logged=activeSets().filter(x=>x.completion_status==='completed'||x.completion_status==='skipped').length;return{logged,planned,pct:planned?Math.round(logged/planned*100):0}}
function nextUnfinishedIndex(day){const slots=dayExercises(day);for(let i=0;i<slots.length;i++){const s=slotByExercise(day,slots[i].exercise.id);if(setsFor(s.exercise.id).length<s.target_sets)return i}return Math.max(0,slots.length-1)}
function rpeUpper(t){const nums=String(t||'').match(/[\d.]+/g)?.map(Number)||[];return nums.length?Math.max(...nums):10}
function workoutScore(session,day){const slots=dayExercises(day);const planned=slots.reduce((n,s)=>n+s.target_sets,0);const sets=(session?.sets||[]).filter(x=>x.completion_status==='completed');const completion=planned?Math.min(1,sets.length/planned):0;const avgRpe=sets.length?sets.reduce((n,x)=>n+(Number(x.rpe)||0),0)/sets.length:0;const rpeScore=avgRpe?Math.max(0,1-Math.abs(avgRpe-7.5)/4):.7;const maxPain=sets.reduce((m,x)=>Math.max(m,Number(x.elbow_pain)||0),0);const painScore=maxPain>=6?.25:maxPain>=4?.65:1;return Math.round((completion*.55+rpeScore*.25+painScore*.20)*100)}

const mediaSlugs=new Set(["dumbbell-bench-press", "incline-machine-press", "machine-shoulder-press", "cable-chest-fly", "cable-lateral-raise", "rope-triceps-pressdown", "treadmill-walk", "neutral-grip-lat-pulldown", "seated-cable-row", "chest-supported-row", "one-arm-cable-row", "rear-delt-fly", "cable-curl", "hammer-curl", "back-extension", "romanian-deadlift", "leg-press-or-squat", "seated-leg-curl", "leg-extension", "calf-raise", "walking-lunge-or-split-squat", "cable-crunch", "incline-dumbbell-press", "lateral-raise", "goblet-squat", "dumbbell-row", "push-up", "glute-bridge", "plank"]);
function mediaPath(e){if(e.image_url?.startsWith('./media/'))return e.image_url;const slug=e.slug==='neutral-grip-pulldown'?'neutral-grip-lat-pulldown':e.slug;return mediaSlugs.has(slug)?`./media/${slug}.webp`:null}
function art(e,large=false){const src=large?mediaPath(e):(e.thumbnail_url||mediaPath(e)),thumb=!large&&!!e.thumbnail_url;return `<div class="exercise-art${large?' large':''}">${src?`<div class="art-frame"><img class="${thumb?'catalog-thumb':''}" src="${esc(src)}" alt="${esc(e.name)} start position" loading="lazy" decoding="async"></div>`:`<div class="empty">${esc(e.name)}<br>Personal exercise</div>`}</div>`}
function movementDemo(e){const src=mediaPath(e);if(e.motion_kind==='still')return art(e,true)+'<p class="muted tiny">Setup illustration. Follow the execution instructions below for the movement.</p>'; return src?`<div class="movement-demo"><div class="sprite" role="img" aria-label="${esc(e.name)}: start and finish positions" style="background-image:url('${src}')"></div></div><div class="row-actions"><button class="secondary" data-demo-pause>Pause</button><button class="secondary" data-demo-speed>Slow speed</button></div><p class="muted tiny">Two-position movement guide${e.slug==='leg-press-or-squat'?' · Leg press variation shown':e.slug==='walking-lunge-or-split-squat'?' · Split squat variation shown':['plank','side-plank'].includes(e.slug)?' · Hold the position and breathe':''}. Read the setup cue below. Muscle highlights are illustrative.</p>`:`<section class="panel"><h2>Movement instructions</h2><p>${esc(e.cue||'Add your setup instructions to this custom exercise.')}</p><p class="muted">Custom exercise: no verified movement illustration.</p></section>`}

function cloudBadge(){return `<div class="cloud ${S.online?'':'offline'}"><i></i>${getQueue().length?`<button class="sync-button" data-action="sync">${getQueue().length} pending · Retry sync</button>`:S.online?'Connected':'Offline mode'}<span class="release">v2.4.2</span></div>`}
function header(title='BodySmith',{back=false,finish=false}={}){const brand=title==='BodySmith'?`<img class="brand-wordmark" src="./brand/wordmark-dark.webp" width="172" height="30" alt="BodySmith"><div class="tag">TRAIN TRACK PROGRESS REPEAT</div>`:`<div class="brand">${esc(title)}</div>`;return `<header class="topbar"><button class="iconbtn ${back?'':'brand-home'}" aria-label="${back?'Back':'Home'}" data-action="${back?'back':'home'}">${back?'←':'<img class="brand-mark" src="./brand/mark.png" width="40" height="40" alt="">'}</button><div class="grow">${brand}${S.user?cloudBadge():''}</div>${finish?'<button class="iconbtn" data-action="finish">Finish</button>':S.user?`<button class="avatar" data-nav="profile" aria-label="Profile">${initials(S.user.display_name)}</button>`:'<span></span>'}</header>`}
function nav(){const items=[['plan','clipboard-list'],['exercises','barbell'],['workout','home-2'],['supplements','pill'],['progress','chart-bar'],['profile','user']];return `<nav class="bottom-nav" aria-label="Primary navigation">${items.map(([n,i])=>`<button type="button" data-nav="${n}" class="${S.screen===n?'active':''}" ${S.screen===n?'aria-current="page"':''}><img class="ui-icon" src="./brand/icons/${i}.svg" width="23" height="23" alt=""><small>${n==='workout'?'Home':n[0].toUpperCase()+n.slice(1)}</small></button>`).join('')}</nav>`}

function authView(){const reg=S.authMode==='register';return `<div class="auth-shell"><section class="auth-card"><div class="auth-identity"><img class="brand-mark" src="./brand/mark.png" width="104" height="104" alt=""><img class="brand-wordmark" src="./brand/wordmark-dark.webp" width="260" height="52" alt="BodySmith"><div class="tag">TRAIN TRACK PROGRESS REPEAT</div></div><h1>${reg?'Create your account':'Welcome back'}</h1><p class="muted">${reg?'Your workouts and history will be private to your account.':'Sign in to sync workouts across your devices.'}</p><div class="auth-switch"><button data-authmode="login" class="${!reg?'active':''}">Sign in</button><button data-authmode="register" class="${reg?'active':''}">Create account</button></div>${S.authError?`<div class="form-error">${esc(S.authError)}</div>`:''}<form id="authForm">${reg?`<label class="field">Display name<input name="displayName" autocomplete="name" maxlength="50" placeholder="Your name" required/></label>`:''}<label class="field">Username<input name="username" autocapitalize="none" autocomplete="username" placeholder="Choose a username" required/></label><label class="field">Password<input name="password" type="password" autocomplete="${reg?'new-password':'current-password'}" minlength="6" required/></label><button class="primary huge" type="submit" ${S.busy?'disabled':''}>${S.busy?'Working…':reg?'Create BodySmith account':'Sign in'}</button></form><p class="auth-footnote">Your training. Your progress. Securely synced across your devices.</p></section></div>`}

function shell(content,screen=S.screen){return `<div class="screen">${header('BodySmith')}${!S.online?'<div class="sync-banner">You are offline. Saved cloud data is available; new set entries will sync when the connection returns.</div>':''}${content}${nav()}</div>`}
function exerciseRow(slot){const e=slot.exercise;const prev=previousSets(e.id);const best=prev.find(x=>x.weight!=null);const sub=slot.duration_minutes?`${slot.duration_minutes} min • ${slot.target_rpe||'Easy'}`:`${slot.target_sets} sets × ${slot.min_reps}–${slot.max_reps} reps`;return `<button class="exercise-row" data-ex="${e.id}">${art(e)}<div class="exercise-copy"><strong>${esc(e.name)}</strong><span>${esc(sub)}</span>${best?`<span>Last: ${best.weight||0} ${S.user.units} × ${best.reps||0}</span>`:''}</div><div class="muscle">${esc(e.primary_muscle||'')}</div><span class="chev">›</span></button>`}
function baseHome(){const d=selectedDay(),slots=dayExercises(d);if(!d)return shell(`<div class="empty">No workout plan found.</div>`);const active=S.active&&S.active.status==='in_progress';return shell(`<section class="card plan-banner"><div class="bolt"><img class="ui-icon" src="./brand/icons/barbell.svg" width="23" height="23" alt=""></div><div><span class="muted tiny">Active Plan</span><h2 style="margin:2px 0">${esc(S.plan.name)}</h2><p class="muted tiny" style="margin:0">${esc(S.plan.goal||'Build strength')} • ${S.plan.days_per_week} days/week</p></div><span class="pill">${S.plan.days_per_week}-day split</span></section><div class="section-title"><h1>${active?'Resume workout':'Your next workout'}</h1><span class="muted">${active?'In progress':'Today'}</span></div><div class="day-tabs">${days().map(x=>`<button data-day="${x.id}" class="${x.id===d.id?'active':''}">${esc(x.name)}</button>`).join('')}</div><section class="card"><div class="workout-head"><div><h2>${esc(d.name)}</h2><p class="muted">${esc(d.focus||'')}</p></div><span class="pill">${slots.length} exercises</span></div><button class="primary huge dashboard-start" data-action="${active&&S.active.plan_day_id===d.id?'resume':'start'}" data-day="${d.id}">${active&&S.active.plan_day_id===d.id?'Resume Workout':'Start Workout'}</button>${slots.map(s=>exerciseRow(s)).join('')}</section>`,'workout')}
function planView(){return shell(`${planControls()}<div class="section-title"><h1>Training Plan</h1><span class="muted">${S.plan.days_per_week} days/week</span></div><section class="card plan-banner"><div class="bolt"><img class="ui-icon" src="./brand/icons/barbell.svg" width="23" height="23" alt=""></div><div><h2 style="margin:0">${esc(S.plan.name)}</h2><p class="muted" style="margin:4px 0 0">${esc(S.plan.goal||'')}</p></div></section>${days().map(d=>`<details class="panel day-card" ${d.id===selectedDay()?.id?'open':''}><summary><div><strong>${esc(d.name)}</strong><div class="muted tiny">${esc(d.focus||'')}</div></div><span class="pill">${dayExercises(d).length} exercises</span></summary><div class="day-exercises">${dayExercises(d).map(s=>`<div class="mini-row"><div><strong>${esc(s.exercise.name)}</strong><div class="muted tiny">${s.duration_minutes?`${s.duration_minutes} min`:`${s.target_sets} × ${s.min_reps}–${s.max_reps}`} • RPE ${esc(s.target_rpe||'—')} • Rest ${s.rest_seconds||0}s</div></div><button class="secondary" data-ex="${s.exercise.id}">View</button></div>`).join('')}<button class="primary huge" data-action="start" data-day="${d.id}">Start ${esc(d.name)}</button></div></details>`).join('')}`,'plan')}
const normalizeSearch=value=>String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
function selectableExercises(){return allExercises().filter(e=>!e.is_legacy)}
function searchExercises(query='',filters={}){const words=normalizeSearch(query).split(' ').filter(Boolean),favorites=new Set(S.user?.preferences?.favorites||[]);return selectableExercises().filter(e=>{const text=normalizeSearch([e.name,e.canonical_name,...(e.aliases||[]),e.primary_muscle,...(e.secondary_muscles||[]),e.equipment,e.movement_pattern||e.movement_type].join(' '));return words.every(w=>text.includes(w))&&(!filters.muscle||e.primary_muscle===filters.muscle)&&(!filters.equipment||e.equipment===filters.equipment)&&(!filters.movement||(e.movement_pattern||e.movement_type)===filters.movement)&&(!filters.favorites||favorites.has(e.id))}).sort((a,b)=>{const q=normalizeSearch(query);return Number(normalizeSearch(b.name)===q)-Number(normalizeSearch(a.name)===q)||a.name.localeCompare(b.name)})}
function catalogFilters(filters={},prefix='library'){return `<div class="catalog-filters">${[['muscle','Muscle','primary_muscle'],['equipment','Equipment','equipment'],['movement','Movement type','movement_pattern']].map(([k,label,field])=>`<label class="field">${label}<select data-catalog-filter="${prefix}:${k}"><option value="">All ${label.toLowerCase()}</option>${[...new Set(selectableExercises().map(e=>e[field]|| (field==='movement_pattern'?e.movement_type:'')).filter(Boolean))].sort().map(v=>`<option value="${esc(v)}" ${filters[k]===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`).join('')}</div>`}
function exercisesView(){const list=searchExercises(S.search,{...S.libraryFilters,favorites:S.favoritesOnly});return shell(`<div class="section-title"><h1>Exercises</h1><span class="muted">${selectableExercises().length} movements</span></div><div class="search"><input id="searchExercises" aria-label="Search exercise, alias, muscle, equipment" placeholder="Search name, alias, muscle, equipment" value="${esc(S.search)}"/></div>${catalogFilters(S.libraryFilters)}<div class="row-actions"><button class="secondary" data-extra="customexercise">Add custom exercise</button><button class="secondary" data-extra="favorites" aria-pressed="${!!S.favoritesOnly}">${S.favoritesOnly?'Show all':'Favorites'}</button><span class="muted" aria-live="polite">${list.length} results</span></div><section class="card">${list.map(e=>`<button class="exercise-row" data-ex="${e.id}">${art(e)}<div class="exercise-copy"><strong>${esc(e.name)}</strong><span>${esc(e.equipment||'Gym')} · ${esc(e.primary_muscle||'')}</span></div><span class="chev">›</span></button>`).join('')||'<div class="empty">No exercises match these filters.</div>'}</section>`,'exercises')}

function detailView(){const e=S.detail;const slots=[];for(const d of days())for(const s of dayExercises(d))if(s.exercise.id===e.id)slots.push({day:d,slot:s});const slot=(S.activeDay?slotByExercise(S.activeDay,e.id):null)||slots[0]?.slot;const prev=previousSets(e.id);const weights=prev.map(x=>Number(x.weight)||0).filter(Boolean);const max=weights.length?Math.max(...weights):0;return `<div class="screen">${header(e.name,{back:true})}${movementDemo(e)}<button class="secondary" data-favorite="${e.id}">${(S.user.preferences?.favorites||[]).includes(e.id)?'★ Favorited':'☆ Add favorite'}</button><div class="chips"><span>${esc(e.primary_muscle||'')}</span><span>${esc(e.equipment||'Gym')}</span><span>${esc(e.movement_type||'Movement')}</span></div><section class="panel"><h3>Setup</h3><p>${esc(e.setup_instructions||e.cue||'Set up with stable support.')}</p><h3>Movement</h3><p>${esc(e.movement_instructions||e.cue||'Move with control.')}</p><div class="coach-note">${esc(e.cue||'Use a controlled, comfortable range.')}</div><p class="muted tiny">Primary: ${esc(e.primary_muscle)} · Secondary: ${esc((e.secondary_muscles||[]).join(', ')||'—')}<br>${esc(e.difficulty||'Self-directed')} · ${esc(e.laterality||'')} · ${esc(e.exercise_type||'')}</p>${e.common_mistakes?.length?`<details><summary>Common mistakes</summary><ul>${e.common_mistakes.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>`:''}</section>${slot?`<div class="stats-grid"><div class="stat"><span>Sets</span><strong>${slot.target_sets}</strong></div><div class="stat"><span>Rep target</span><strong>${slot.duration_minutes?`${slot.duration_minutes}m`:`${slot.min_reps}–${slot.max_reps}`}</strong></div><div class="stat"><span>RPE</span><strong>${esc(slot.target_rpe||'—')}</strong></div><div class="stat"><span>Rest</span><strong>${slot.rest_seconds||0}s</strong></div></div>`:''}<section class="panel"><h3>Progression</h3><p>${esc(slot?.progression_rule||'Add reps before load while form remains clean.')}</p>${slot?.pain_rule?`<div class="pain">${esc(slot.pain_rule)}</div>`:''}</section><section class="panel"><h3>Recent performance</h3>${prev.length?`<div class="stats-grid"><div class="stat"><span>Best load</span><strong>${max} ${S.user.units}</strong></div><div class="stat"><span>Sets last time</span><strong>${prev.length}</strong></div></div>${prev.map(x=>`<div class="mini-row"><span>Set ${x.set_number}</span><strong>${x.weight??'—'} ${S.user.units} × ${x.reps??'—'} <span class="muted">RPE ${x.rpe??'—'}</span></strong></div>`).join('')}`:'<div class="empty">Log this exercise to start building your history.</div>'}</section><section class="panel"><h3>Similar movements</h3>${substitutes(e,false).slice(0,6).map(a=>`<button class="secondary huge" data-ex="${a.id}">${esc(a.name)} · ${esc(a.equipment)}</button>`).join('')||'<p class="muted">No close match in the current catalog.</p>'}</section>${(S.active?[]:slots).map(({day})=>`<button class="primary huge" data-action="start" data-day="${day.id}">Start ${esc(day.name)}</button>`).join('')}</div>`}

function baseActiveView(){const day=S.activeDay,slots=dayExercises(day),slot=slots[S.activeIndex]||slots[0];if(!slot)return home();const ex=slot.exercise,logs=setsFor(ex.id),cur=Array.from({length:slot.target_sets},(_,n)=>n+1).find(n=>!logs.some(x=>x.set_number===n))||slot.target_sets,prev=previousSets(ex.id),p=activeProgress();const last=logs.filter(x=>x.completion_status==='completed').at(-1)||prev[Math.min(logs.length,Math.max(0,prev.length-1))]||{};const alternates=swapChoices(ex);return `<div class="screen">${header(day.name,{finish:true})}<div class="session-strip"><span>${p.logged}/${p.planned} sets logged</span><span>${p.pct}% complete</span></div><div class="progress"><div style="width:${p.pct}%"></div></div>${S.rest>0?`<div class="rest-card"><span>Rest timer</span><strong>${fmtTime(S.rest)}</strong><button data-action="skiprest">Skip</button></div>`:''}<button class="demo-open" data-ex="${ex.id}">${art(ex,true)}<span>Tap for movement demonstration</span></button><div class="active-title"><div><h1>${esc(ex.name)}</h1><p class="muted" style="margin:5px 0">${slot.duration_minutes?'Timed exercise':`${slot.rest_seconds||0} sec rest`} · ${/dumbbell/i.test(ex.equipment||'')?'Weight per dumbbell':'Load as shown on equipment'}</p></div><span class="setcount">Set ${cur}/${slot.target_sets}</span></div><div class="chips"><span>${slot.target_sets} sets</span>${slot.duration_minutes?`<span>${slot.duration_minutes} min</span>`:`<span>${slot.min_reps}–${slot.max_reps} reps</span>`}<span>RPE ${esc(slot.target_rpe||'—')}</span><span>${esc(ex.primary_muscle||'')}</span></div><section class="panel coach-cue"><b>Coach cue</b><p style="margin:6px 0 0">${esc(ex.cue||'Move with control.')}</p></section><div id="painBox"></div><div class="set-table"><div class="set-head"><span>Set</span><span>Last</span><span>${slot.duration_minutes?'Minutes':'Reps'}</span><span>${slot.duration_minutes?'Status':S.user.units}</span></div>${Array.from({length:slot.target_sets}).map((_,i)=>{const l=logs.find(x=>x.set_number===i+1),pv=prev.find(x=>x.set_number===i+1),current=!l&&i===Array.from({length:slot.target_sets},(_,n)=>n).find(n=>!logs.some(x=>x.set_number===n+1));return `<div ${l?`role="button" tabindex="0" data-edit-set="${ex.id}:${i+1}" aria-label="Edit set ${i+1}"`:""} class="set-line ${current?'current':''}"><b>${i+1}</b><span>${pv?slot.duration_minutes?`${pv.duration_seconds?pv.duration_seconds/60:pv.reps||slot.duration_minutes} min`:`${pv.weight??'—'} × ${pv.reps??'—'}`:'—'}</span><span>${l?l.completion_status==='skipped'?'Skipped':slot.duration_minutes?(l.duration_seconds?l.duration_seconds/60:l.reps??'—'):l.reps??'—':current?`<input id="reps" aria-label="Actual reps or minutes" inputmode="decimal" value="${slot.duration_minutes?slot.duration_minutes:(last.reps||slot.min_reps||'')}"/>`:'—'}</span><span>${l?l.completion_status==='skipped'?'—':slot.duration_minutes?'Done':l.weight??'—':current?slot.duration_minutes?'<span class="muted">Cardio</span>':`<input id="weight" aria-label="Weight" inputmode="decimal" value="${last.weight??''}"/>`:'—'}</span></div>`}).join('')}</div>${logs.length<slot.target_sets?`<div class="quick-grid"><label class="field">RPE <span class="muted tiny">5 easy · 7–8 challenging with about 2–3 reps left · 10 max effort</span><input id="rpe" inputmode="decimal" value="${slot.duration_minutes?'':(last.rpe||7.5)}" placeholder="1–10"/></label><label class="field">Elbow pain<input id="painInput" inputmode="numeric" value="0" min="0" max="10"/></label></div><label class="field">Set note<input id="setNote" maxlength="200" placeholder="Optional note"/></label><button class="primary huge" data-action="logset">✓ Log Set</button>`:`<div class="coach-note">Exercise complete.</div>`}<div class="row-actions"><button class="secondary" data-action="prevexercise">← Previous</button><button class="secondary" data-action="nextexercise">Next →</button></div><div class="row-actions"><button class="secondary" data-action="toggleswap">Swap exercise</button><button class="dangerbtn" data-action="skipexercise">Skip exercise</button></div><section class="panel swap-panel ${S.swapOpen?'show':''}"><h3>Swap ${esc(ex.name)}</h3><p class="muted tiny">${S.swapBrowseAll?'Search the full exercise library by name, alias, muscle or equipment.':'Suggested first: similar movements that fit this slot.'}</p>${logs.length?`<div class="pain">You already logged ${logs.length} set${logs.length===1?'':'s'} for this exercise. Delete those logged sets before changing this slot.</div>`:''}<div class="row-actions"><button class="${!S.swapBrowseAll?'primary':'secondary'}" data-swap-mode="suggested">Suggested</button><button class="${S.swapBrowseAll?'primary':'secondary'}" data-swap-mode="all">Browse full library</button></div>${S.swapBrowseAll?`<label class="field">Search all exercises<input id="swapSearch" value="${esc(S.swapSearch||'')}" placeholder="Try legs, cable, bench, row…"></label><p class="muted tiny">${alternates.length} matching movements shown. Search reaches the full library.</p>`:''}<div class="swap-options">${alternates.map(a=>`<button data-swap="${a.id}"><span>${esc(a.name)}</span><span class="muted">${esc(a.equipment||'')} · ${esc(a.primary_muscle||'')}</span></button>`).join('')||'<div class="muted">No matching exercises. Try a different search.</div>'}</div></section></div>`}
function summaryView(){const session=S.active,day=S.activeDay,sets=(session?.sets||[]).filter(x=>x.completion_status==='completed'),score=workoutScore(session,day),planned=dayExercises(day).reduce((n,s)=>n+s.target_sets,0),pct=planned?Math.round((session?.sets||[]).length/planned*100):0,avg=sets.length?(sets.reduce((n,x)=>n+(Number(x.rpe)||0),0)/sets.length).toFixed(1):'—',pain=sets.length?(sets.reduce((n,x)=>n+(Number(x.elbow_pain)||0),0)/sets.length).toFixed(1):'0',duration=Math.round((Date.now()-new Date(session.started_at).getTime())/1000);return `<div class="screen">${header('BodySmith')}<div class="section-title"><div><h1>Workout Summary</h1><p class="muted" style="margin:4px 0">${esc(day.name)} · Review before saving</p></div></div><section class="card summary-hero"><div class="ring" style="--pct:${Math.min(100,pct)*3.6}deg"><strong>${Math.min(100,pct)}%</strong><span>COMPLETE</span></div><div><span class="muted">BodySmith Score</span><h1 style="font-size:45px;margin:3px 0">${score}</h1><span style="color:var(--good)">▲ Session score</span></div></section><div class="stats-grid"><div class="stat"><span>Duration</span><strong>${fmtDur(duration)}</strong></div><div class="stat"><span>Sets logged</span><strong>${sets.length}</strong></div><div class="stat"><span>Avg RPE</span><strong>${avg}</strong></div><div class="stat"><span>Avg pain</span><strong>${pain}/10</strong></div></div><section class="panel"><h3>Session metrics</h3>${sessionComparison(session)}${sessionDetails(session)}</section><section class="panel"><h3>Completed exercises</h3>${dayExercises(day).map(s=>{const xs=(session.sets||[]).filter(x=>x.exercise_id===s.exercise.id),ok=xs.filter(x=>x.completion_status==='completed').length>=s.target_sets;return `<div class="summary-row">${art(s.exercise)}<div><strong>${esc(s.exercise.name)}</strong><div class="muted tiny">${xs.filter(x=>x.completion_status==='completed').length}/${s.target_sets} sets logged</div></div><span class="${ok?'check':'muted'}">${ok?'✓':'•'}</span></div>`}).join('')}</section><section class="panel"><h3>Coach notes</h3>${coachNotes(session,day).map(n=>`<div class="coach-note">${esc(n)}</div>`).join('')}</section><button class="secondary huge" data-action="resume">← Return to workout</button><button class="primary huge" data-action="complete">✓ Save & Finish</button></div>`}
function coachNotes(session,day){const notes=[];const sets=(session?.sets||[]).filter(x=>x.completion_status==='completed');const maxPain=sets.reduce((m,x)=>Math.max(m,Number(x.elbow_pain)||0),0);if(maxPain>=6)notes.push('One movement reached 6+/10 elbow pain. Stop or swap that movement next time and keep the replacement pain-free.');else if(maxPain>=4)notes.push('Elbow pain entered the caution range. Reduce load or arm volume if it returns next session.');for(const slot of dayExercises(day)){const xs=sets.filter(x=>x.exercise_id===slot.exercise.id);if(!slot.duration_minutes&&xs.length>=slot.target_sets&&xs.every(x=>(Number(x.reps)||0)>=slot.max_reps&&(Number(x.rpe)||10)<=rpeUpper(slot.target_rpe))){notes.push(`${slot.exercise.name}: you reached the top of the rep range at target effort. Consider a small load increase next time.`);break}}if(!notes.length)notes.push(sets.length<dayExercises(day).reduce((n,x)=>n+x.target_sets,0)?'This workout has unfinished sets. Return to continue, or save the work you completed.':'Keep adding reps within the target ranges before increasing load.');return notes}
function progressView(){const completed=S.history.filter(x=>x.status==='completed');const cutoff=Date.now()-30*86400000;const recent=completed.filter(x=>new Date(x.started_at).getTime()>=cutoff);const sets=recent.flatMap(x=>x.sets||[]).filter(x=>x.completion_status==='completed');const avgRpe=sets.length?(sets.reduce((n,x)=>n+(Number(x.rpe)||0),0)/sets.length).toFixed(1):'—';const avgPain=sets.length?(sets.reduce((n,x)=>n+(Number(x.elbow_pain)||0),0)/sets.length).toFixed(1):'—';const bestMap={};for(const h of completed)for(const x of h.sets||[]){if(x.completion_status!=='completed'||x.weight==null)continue;bestMap[x.exercise_id]=Math.max(bestMap[x.exercise_id]||0,(Number(x.weight)||0)*((x.units||'lb')===S.user.units?1:S.user.units==='kg'?1/2.2046226218:2.2046226218))}const top=Object.entries(bestMap).map(([id,w])=>({e:allExercises().find(e=>e.id===id),w})).filter(x=>x.e).sort((a,b)=>b.w-a.w).slice(0,7);const maxTop=Math.max(1,...top.map(x=>x.w));return shell(`<div class="section-title"><h1>Progress</h1><span class="muted">Last 30 days</span></div><div class="stats-grid"><div class="stat"><span>Workouts</span><strong>${recent.length}</strong></div><div class="stat"><span>Sets</span><strong>${sets.length}</strong></div><div class="stat"><span>Avg RPE</span><strong>${avgRpe}</strong></div><div class="stat"><span>Avg pain</span><strong>${avgPain}</strong></div></div><section class="panel">${progressMetrics()}<h3>Best logged loads (${S.user.units})</h3>${top.length?`<div class="bar-list">${top.map(x=>`<div class="bar-row"><span class="tiny">${esc(x.e.name)}</span><div class="bar"><i style="width:${Math.round(x.w/maxTop*100)}%"></i></div><strong>${Math.round(x.w*10)/10}</strong></div>`).join('')}</div>`:'<div class="empty">Complete workouts to build your progress chart.</div>'}</section><section class="panel"><h3>Workout history</h3>${S.history.filter(x=>x.status!=='in_progress').slice(0,20).map(historyRow).join('')||'<div class="empty">No completed workouts yet.</div>'}</section>`,'progress')}
function historyRow(h){const day=h.day_snapshot||dayById(h.plan_day_id)||h.day||{},sets=(h.sets||[]).filter(x=>x.completion_status==='completed');const avg=sets.length?(sets.reduce((n,x)=>n+(Number(x.rpe)||0),0)/sets.length).toFixed(1):'—';return `<details class="history-detail"><summary><div class="history-card"><div><strong>${esc(day.name||'Workout')}${h.status==='abandoned'?' · Partial':''}</strong><div class="meta">${new Date(h.started_at).toLocaleDateString()} • ${sets.length} sets • Avg RPE ${avg}</div></div><span class="pill">${h.duration_seconds?fmtDur(h.duration_seconds):'Saved'}</span></div></summary>${sessionDetails(h)}${h.status==='completed'?`<button class="secondary huge" data-history-edit="${h.id}">Edit Workout</button>`:""}</details>`}
function profileView(){return shell(`${loadingSettingsView()}${notificationPanel()}<button class="secondary huge" data-extra="editprofile">Training preferences & schedule</button>${checkinHistory()}<div class="section-title"><h1>Profile</h1><span class="muted">Cloud account</span></div><section class="card"><div class="profile-head"><div class="profile-avatar">${initials(S.user.display_name)}</div><div><h2 style="margin:0">${esc(S.user.display_name)}</h2><p class="muted" style="margin:4px 0">@${esc(S.user.username)}</p></div></div><label class="field">Display name<input id="displayName" value="${esc(S.user.display_name)}" maxlength="50"/></label><div class="field"><span>Units</span><div class="segmented"><button data-units="lb" class="${S.user.units==='lb'?'active':''}">Pounds (lb)</button><button data-units="kg" class="${S.user.units==='kg'?'active':''}">Kilograms (kg)</button></div></div><button class="primary huge" data-action="saveprofile">Save profile</button></section><section class="panel"><h3>Daily check-in</h3><div class="quick-grid"><label class="field">Body weight<input id="checkWeight" inputmode="decimal" placeholder="Optional"/></label><label class="field">Elbow pain<input id="checkPain" inputmode="numeric" placeholder="0–10"/></label></div><div class="quick-grid"><label class="field">Calories<input id="checkCalories" inputmode="numeric" placeholder="Optional"/></label><label class="field">Protein (g)<input id="checkProtein" inputmode="numeric" placeholder="Optional"/></label></div><label class="field">Steps<input id="checkSteps" inputmode="numeric" placeholder="Optional"/></label><label class="field">Notes<textarea id="checkNotes" placeholder="Recovery, sleep, soreness, anything useful"></textarea></label><button class="secondary huge" data-action="checkin">Save check-in</button></section><section class="panel"><h3>Account</h3><p class="muted">Your workout history is stored separately from every other BodySmith user.</p><button class="dangerbtn huge" data-action="logout">Sign out</button></section>`,'profile')}
function render(){if(!S.token||!S.user){app.innerHTML=authView();bind();return}if(!S.user.onboarding_completed){app.innerHTML=onboardingView();bind();bindExtras();return}if(S.editHistory){app.innerHTML=historyEditorView();bind();return}if(S.editor){app.innerHTML=editorView();bind();bindExtras();return}if(S.screen==='supplements'){app.innerHTML=supplementsView();bind();bindExtras();return}if(S.detail){app.innerHTML=detailView();bind();return}if(S.screen==='active'&&S.active){app.innerHTML=activeView();bind();return}if(S.screen==='summary'&&S.active){app.innerHTML=summaryView();bind();return}if(S.screen==='plan')app.innerHTML=planView();else if(S.screen==='exercises')app.innerHTML=exercisesView();else if(S.screen==='progress')app.innerHTML=progressView();else if(S.screen==='profile')app.innerHTML=profileView();else app.innerHTML=home();bind()}

async function bootstrap(){scopeStorage();if(!S.token){render();return}S.busy=true;try{await syncQueue();const data=await api('bootstrap');S.user=data.user;scopeStorage();S.exercises=data.exercises||[];S.plans=data.plans||[];S.supplements=data.supplements||[];S.supplementLogs=data.supplementLogs||[];S.checkins=data.checkins||[];S.plan=data.plan;S.history=data.history||[];S.active=data.activeSession||null;if(S.active){S.activeDay=structuredClone(S.active.day_snapshot||dayById(S.active.plan_day_id));S.activeIndex=nextUnfinishedIndex(S.activeDay)}if(getQueue().length){const local=cache();if(local.user?.id===S.user.id){S.active=local.active||null;S.history=local.history||S.history;S.supplementLogs=local.supplementLogs||S.supplementLogs;if(S.active){S.activeDay=structuredClone(S.active.day_snapshot||dayById(S.active.plan_day_id));S.activeIndex=nextUnfinishedIndex(S.activeDay)}}}S.selectedDayId=nextDay()?.id||days()[0]?.id||null;setCache({user:S.user,plan:S.plan,history:S.history,active:S.active});await syncQueue();}catch(e){if(e.status===401){rememberPendingAccount();localStorage.removeItem(TOKEN_KEY);S.token='';S.user=null;S.authError='Your session expired. Sign in to the same account to restore and sync saved entries.'}else{const c=cache();if(c.user&&c.plan){S.user=c.user;S.exercises=c.exercises||[];S.plans=c.plans||[];S.supplements=c.supplements||[];S.supplementLogs=c.supplementLogs||[];S.checkins=c.checkins||[];S.plan=c.plan;S.history=c.history||[];S.active=c.active||null;S.online=false;if(S.active){S.activeDay=structuredClone(S.active.day_snapshot||dayById(S.active.plan_day_id));S.activeIndex=nextUnfinishedIndex(S.activeDay)}toast('Using saved offline data');}else{S.authError='Could not reach BodySmith. Check your connection and try again.'}}}finally{S.busy=false;render()}}
async function syncQueue(){if(!S.online||!S.token||S.syncing)return;S.syncing=true;try{let q=getQueue();while(q.length){const item=q[0];try{await api(item.action,item.payload,{timeout:10000})}catch(e){S.syncError=e.message;break}S.syncError='';q=getQueue();q.shift();setQueue(q)} }finally{S.syncing=false}}
function queue(action,payload){const q=getQueue();q.push({action,payload,at:Date.now()});setQueue(q)}
async function submitAuth(form){if(S.busy)return;S.authError='';S.busy=true;const fd=new FormData(form);try{const data=await api(S.authMode==='register'?'register':'login',{username:fd.get('username'),password:fd.get('password'),displayName:fd.get('displayName')||undefined});S.token=data.token;localStorage.setItem(TOKEN_KEY,S.token);S.user=data.user;restorePendingAccount();toast(S.authMode==='register'?'Account created':'Signed in');await bootstrap()}catch(e){S.authError=e.message||'Sign in failed';S.busy=false;render()}}
async function startWorkout(dayId){if(S.active){resumeWorkout();toast('Resumed your active workout. Finish it before starting another.');return}if(!S.online){toast('Connect to the internet to start a new cloud workout.',true);return}S.busy=true;try{const data=await api('start_session',{planDayId:dayId});S.active={...data.session,sets:data.session.sets||[]};S.activeDay=structuredClone(data.session.day_snapshot||dayById(dayId));S.activeIndex=0;S.screen='active';cacheWorkoutMedia();S.detail=null;setCache({user:S.user,plan:S.plan,history:S.history,active:S.active});render()}catch(e){toast(e.message,true)}finally{S.busy=false}}
function resumeWorkout(){if(!S.active)return;const until=Number(localStorage.getItem(CACHE_KEY+'-rest')||0);if(until>Date.now())setRest(Math.ceil((until-Date.now())/1000));S.activeDay=structuredClone(S.active.day_snapshot||dayById(S.active.plan_day_id));S.activeIndex=nextUnfinishedIndex(S.activeDay);cacheWorkoutMedia();S.screen='active';S.detail=null;render()}
function setRest(sec){clearInterval(S.restTimer);S.rest=Math.max(0,Number(sec)||0);S.restEnd=Date.now()+S.rest*1000;localStorage.setItem(CACHE_KEY+'-rest',String(S.restEnd));if(S.rest>0)S.restTimer=setInterval(()=>{S.rest=Math.max(0,Math.ceil((S.restEnd-Date.now())/1000));const el=document.querySelector('.rest-card strong');if(el)el.textContent=fmtTime(S.rest);if(!S.rest){clearInterval(S.restTimer);toast('Rest complete. Ready for your next set.');navigator.vibrate?.([150,90,150])}},1000)}
function cacheWorkoutMedia(){if(!S.activeDay||!navigator.serviceWorker?.controller)return;const slots=dayExercises(S.activeDay),current=slots.slice(S.activeIndex,S.activeIndex+2).map(s=>mediaPath(s.exercise)),thumbs=slots.map(s=>s.exercise.thumbnail_url).filter(Boolean);navigator.serviceWorker.controller.postMessage({type:'CACHE_WORKOUT',urls:[...new Set([...current,...thumbs].filter(Boolean))]});}
function persist(){if(S.active&&S.activeDay)S.active.day_snapshot=S.activeDay;setCache({user:S.user,plan:S.plan,history:S.history,active:S.active});}
function rememberPendingAccount(){const c=cache();if(!c.user?.id||!getQueue().length)return;let entries={};try{entries=JSON.parse(localStorage.getItem('bodysmith-recovery-v3')||'{}')}catch{}entries[c.user.id]={cacheKey:CACHE_KEY,queueKey:QUEUE_KEY};localStorage.setItem('bodysmith-recovery-v3',JSON.stringify(entries));}
function restorePendingAccount(){let entries={};try{entries=JSON.parse(localStorage.getItem('bodysmith-recovery-v3')||'{}')}catch{}const old=entries[S.user.id];scopeStorage();if(old){const c=localStorage.getItem(old.cacheKey),q=localStorage.getItem(old.queueKey);if(c&&q&&JSON.parse(c).user?.id===S.user.id){localStorage.setItem(CACHE_KEY,c);localStorage.setItem(QUEUE_KEY,q)}delete entries[S.user.id];localStorage.setItem('bodysmith-recovery-v3',JSON.stringify(entries));}}

function scopeStorage(){CACHE_KEY='bodysmith-cache-v3-'+S.token.slice(-24);QUEUE_KEY='bodysmith-queue-v3-'+S.token.slice(-24);const old=JSON.parse(localStorage.getItem('bodysmith-cache-v2')||'null');if(old&&old.user?.id===S.user?.id&&S.token&&!localStorage.getItem(CACHE_KEY)){localStorage.setItem(CACHE_KEY,JSON.stringify(old));const q=localStorage.getItem('bodysmith-queue-v2');if(q)localStorage.setItem(QUEUE_KEY,q);localStorage.removeItem('bodysmith-cache-v2');localStorage.removeItem('bodysmith-queue-v2')}}
async function logSet(){
 if(S.saveBusy)return;const slot=dayExercises(S.activeDay)[S.activeIndex],ex=slot.exercise,existing=setsFor(ex.id);if(existing.length>=slot.target_sets)return;
 const value=id=>document.getElementById(id)?.value??'';const reps=value('reps'),weight=value('weight'),rpe=value('rpe'),pain=value('painInput');
 if(!reps||!Number.isFinite(+reps)||+reps<=0||(!slot.duration_minutes&&!Number.isInteger(+reps))||(+weight<0)||!Number.isFinite(+weight)||(rpe!==''&&(!Number.isFinite(+rpe)||+rpe<1||+rpe>10))||!Number.isFinite(+pain)||+pain<0||+pain>10){toast('Check reps/time, weight, RPE (1–10), and pain (0–10).',true);return}
 const payload={sessionId:S.active.id,exerciseId:ex.id,units:S.user.units,loadBasis:loadSettings(ex).basis,loadMultiplier:(loadSettings(ex).basis==='per_side'||loadSettings(ex).basis==='per_dumbbell'&&ex.laterality==='Bilateral')?2:1,setNumber:Array.from({length:slot.target_sets},(_,i)=>i+1).find(n=>!existing.some(x=>x.set_number===n)),reps:slot.duration_minutes?null:+reps,durationSeconds:slot.duration_minutes?Math.round(+reps*60):null,weight:weight===''?null:+weight,rpe:rpe===''?null:+rpe,elbowPain:+pain,notes:value('setNote'),completionStatus:'completed'};
 const local={id:crypto.randomUUID(),session_id:S.active.id,exercise_id:ex.id,set_number:payload.setNumber,reps:payload.reps,weight:payload.weight,rpe:payload.rpe,elbow_pain:payload.elbowPain,duration_seconds:payload.durationSeconds,units:S.user.units,load_basis:payload.loadBasis,load_multiplier:payload.loadMultiplier,notes:payload.notes,completion_status:'completed',logged_at:new Date().toISOString()};
 S.saveBusy=true;try{S.active.sets.push(local);queue('save_set',payload);persist();setRest(slot.rest_seconds||0);navigator.vibrate?.(50);const old=previousSets(ex.id);if(old.length&&+weight>Math.max(...S.history.filter(h=>h.status==='completed').flatMap(h=>(h.sets||[]).filter(x=>x.exercise_id===ex.id&&x.completion_status==='completed').map(x=>(+x.weight||0)*((x.units||'lb')===S.user.units?1:S.user.units==='kg'?1/2.2046226218:2.2046226218)))))toast('New load record for this exercise!');render();await syncQueue();}finally{S.saveBusy=false}
}
async function skipExercise(){if(S.saveBusy)return;S.saveBusy=true;try{const slot=dayExercises(S.activeDay)[S.activeIndex],ex=slot.exercise;for(let i=1;i<=slot.target_sets;i++){if(setsFor(ex.id).some(x=>x.set_number===i))continue;const payload={sessionId:S.active.id,exerciseId:ex.id,setNumber:i,completionStatus:'skipped',notes:'Skipped'};S.active.sets.push({id:crypto.randomUUID(),exercise_id:ex.id,set_number:i,completion_status:'skipped'});queue('save_set',payload)}persist();if(S.activeIndex<dayExercises(S.activeDay).length-1)S.activeIndex++;render();await syncQueue();}finally{S.saveBusy=false}}
function pattern(e){const n=e.name.toLowerCase();if(/pulldown/.test(n))return'vertical pull';if(/row/.test(n))return'horizontal pull';if(/shoulder press/.test(n))return'vertical push';if(/pressdown/.test(n))return'elbow extension';if(/leg curl/.test(n))return'knee flexion';if(/curl/.test(n))return'elbow flexion';if(/chest fly/.test(n))return'chest fly';if(/bench|incline.*press|push.up/.test(n))return'horizontal push';if(/lateral/.test(n))return'lateral raise';return e.movement_type+' '+e.primary_muscle}
function substitutes(ex,excludeDay=true){const occupied=new Set(excludeDay?dayExercises(S.activeDay).map(s=>s.exercise.id):[ex.id]);return selectableExercises().filter(a=>a.id!==ex.id&&!occupied.has(a.id)&&(ex.substitution_group?a.substitution_group===ex.substitution_group:pattern(a)===pattern(ex))).sort((a,b)=>Number(b.equipment===ex.equipment)-Number(a.equipment===ex.equipment)||a.name.localeCompare(b.name)).slice(0,16)}
function swapChoices(ex){
 const occupied=new Set(dayExercises(S.activeDay).map(s=>s.exercise.id));
 if(!S.swapBrowseAll)return substitutes(ex);
 return searchExercises(S.swapSearch||'').filter(a=>a.id!==ex.id&&!occupied.has(a.id)).slice(0,60)
}
async function swapExercise(id){const alt=allExercises().find(e=>e.id===id),slot=dayExercises(S.activeDay)[S.activeIndex];if(!alt)return;if(setsFor(slot.exercise.id).length){toast('Substitute before logging sets for this exercise.',true);return}const base=S.activeDay.plan_day_exercises.find(x=>x.id===slot.id);base.exercises=alt;base.exercise_id=id;queue('swap_exercise',{sessionId:S.active.id,slotId:slot.id,exerciseId:id});S.swapOpen=false;S.swapBrowseAll=false;S.swapSearch='';persist();cacheWorkoutMedia();render();await syncQueue();toast('Substitution saved for this workout')}
function showSummary(){S.screen='summary';render()}
async function completeWorkout(){if(!S.active||S.saveBusy)return;setRest(0);S.saveBusy=true;try{const finished={...S.active,status:'completed',completed_at:new Date().toISOString(),duration_seconds:Math.round((Date.now()-new Date(S.active.started_at))/1000),day_snapshot:S.activeDay};queue('complete_session',{sessionId:S.active.id,completedAt:finished.completed_at});S.history=[finished,...S.history.filter(h=>h.id!==finished.id)];S.active=null;S.activeDay=null;S.screen='workout';persist();S.selectedDayId=nextDay()?.id;render();await syncQueue();toast(getQueue().length?'Workout saved on device; sync pending.':'Workout saved to cloud');}finally{S.saveBusy=false}}
async function saveProfile(){const displayName=document.querySelector('#displayName')?.value?.trim();try{const data=await api('update_profile',{displayName,units:S.user.units});S.user=data.user;setCache({user:S.user,plan:S.plan,history:S.history,active:S.active});render();toast('Profile saved')}catch(e){toast(e.message,true)}}
async function saveCheckin(){try{await api('daily_checkin',{date:localDate(),weight:document.querySelector('#checkWeight')?.value,elbowPain:document.querySelector('#checkPain')?.value,calories:document.querySelector('#checkCalories')?.value,protein:document.querySelector('#checkProtein')?.value,steps:document.querySelector('#checkSteps')?.value,notes:document.querySelector('#checkNotes')?.value});await bootstrap();toast('Daily check-in saved')}catch(e){toast(e.message,true)}}
async function logout(){if(S.active||getQueue().length){toast('Finish your workout and sync pending entries before signing out.',true);return}try{const reg=await navigator.serviceWorker?.ready;const sub=await reg?.pushManager?.getSubscription();if(sub){await api('unsubscribe_push',{endpoint:sub.endpoint});await sub.unsubscribe()}}catch{}try{if(S.online)await api('logout')}catch{}localStorage.removeItem(TOKEN_KEY);localStorage.removeItem(CACHE_KEY);localStorage.removeItem(QUEUE_KEY);S.token='';S.user=null;S.plan=null;S.history=[];S.active=null;S.screen='workout';render()}
function painFeedback(){const n=Number(document.querySelector('#painInput')?.value||0),box=document.querySelector('#painBox');if(!box)return;box.innerHTML=n>=6?'<div class="pain danger">6+/10: stop or swap this movement. Do not push through sharp or escalating pain.</div>':n>=4?'<div class="pain">4–5/10: reduce load or volume and use a pain-free variation.</div>':''}

function bind(){
  bindExtras();
  const authForm=document.querySelector('#authForm');if(authForm)authForm.onsubmit=e=>{e.preventDefault();submitAuth(authForm)};
  document.querySelectorAll('[data-authmode]').forEach(b=>b.onclick=()=>{S.authMode=b.dataset.authmode;S.authError='';render()});
  document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{S.screen=b.dataset.nav;S.detail=null;render()});
  document.querySelectorAll('[data-day]').forEach(b=>{if(!b.dataset.action)b.onclick=()=>{S.selectedDayId=b.dataset.day;render()}});
  document.querySelectorAll('[data-ex]').forEach(b=>b.onclick=()=>{S.detail=allExercises().find(e=>e.id===b.dataset.ex)||null;render()});
  document.querySelectorAll('[data-swap]').forEach(b=>b.onclick=()=>swapExercise(b.dataset.swap));
  document.querySelectorAll('[data-swap-mode]').forEach(b=>b.onclick=()=>{S.swapBrowseAll=b.dataset.swapMode==='all';S.swapSearch='';render()});
  const swapSearch=document.querySelector('#swapSearch');if(swapSearch)swapSearch.oninput=e=>{S.swapSearch=e.target.value;const pos=e.target.selectionStart;render();const n=document.querySelector('#swapSearch');n?.focus();n?.setSelectionRange(pos,pos)};
  const search=document.querySelector('#searchExercises');if(search)search.oninput=e=>{S.search=e.target.value;const pos=e.target.selectionStart;render();const n=document.querySelector('#searchExercises');n?.focus();n?.setSelectionRange(pos,pos)};
  const pain=document.querySelector('#painInput');if(pain)pain.oninput=painFeedback;
  document.querySelectorAll('[data-units]').forEach(b=>b.onclick=()=>{S.user.units=b.dataset.units;render()});
  document.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{const a=b.dataset.action;if(a==='noop')return;if(a==='home'){S.screen='workout';S.detail=null;render();return;}if(a==='sync'){await syncQueue();render();toast(getQueue().length?'Still pending. Your entries are saved on this device.':'All entries synced');return;}if(a==='back'){S.detail=null;render()}else if(a==='start')await startWorkout(b.dataset.day||S.selectedDayId||selectedDay()?.id);else if(a==='resume')resumeWorkout();else if(a==='logset')await logSet();else if(a==='skiprest'){setRest(0);render()}else if(a==='prevexercise'){S.activeIndex=Math.max(0,S.activeIndex-1);cacheWorkoutMedia();S.swapOpen=false;S.swapBrowseAll=false;S.swapSearch='';render()}else if(a==='nextexercise'){S.activeIndex=Math.min(dayExercises(S.activeDay).length-1,S.activeIndex+1);cacheWorkoutMedia();S.swapOpen=false;S.swapBrowseAll=false;S.swapSearch='';render()}else if(a==='skipexercise')await skipExercise();else if(a==='toggleswap'){S.swapOpen=!S.swapOpen;if(!S.swapOpen){S.swapBrowseAll=false;S.swapSearch=''}render()}else if(a==='finish')showSummary();else if(a==='complete')await completeWorkout();else if(a==='saveprofile')await saveProfile();else if(a==='checkin')await saveCheckin();else if(a==='logout')await logout()});
}

window.addEventListener('online',async()=>{S.online=true;toast('Back online');await syncQueue();if(S.token&&!S.active)bootstrap()});
window.addEventListener('offline',()=>{S.online=false;toast('Offline. Your workout remains saved on this device.');});
window.addEventListener('beforeunload',e=>{if(S.active||getQueue().length){e.preventDefault();e.returnValue=''}});
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).then(async reg=>{await reg.update();S.pushEnabled=!!(await reg.pushManager?.getSubscription());if(S.screen==='supplements')render()}).catch(()=>{}));
const weekdays=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
const localDate=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const input=(name,label,value='',type='text',attrs='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
const select=(name,label,options,value)=>`<label class="field">${label}<select name="${name}">${options.map(x=>`<option ${String(x)===String(value)?'selected':''}>${esc(x)}</option>`).join('')}</select></label>`;
function dayChecks(selected=[1,2,4,6],name='days'){return `<div class="weekday-checks">${weekdays.map((d,i)=>`<label><input type="checkbox" name="${name}" value="${i}" ${selected.includes(i)?'checked':''}>${d}</label>`).join('')}</div>`}
function onboardingView(){const p=S.user.preferences||{};return `<div class="screen">${header()}<h1>Your training, your way.</h1><p class="muted">Set up your own profile. Every field below belongs to your account.</p><form id="onboardForm" class="panel">${input('displayName','Display name',S.user.display_name,'text','required maxlength="50" minlength="2"')}${select('goal','Training goal',['Build muscle','Build strength','General fitness','Improve consistency'],p.goal||'Build muscle')}${select('experience','Experience',['Beginner','Intermediate','Experienced'],p.experience||'Beginner')}<div class="quick-grid">${select('daysPerWeek','Days per week',[1,2,3,4,5,6,7],p.daysPerWeek||4)}${select('duration','Workout duration (minutes)',[20,30,45,60,75,90],p.duration||60)}</div>${input('equipment','Available equipment',p.equipment||'Gym machines, cables, dumbbells','text','required')}${select('units','Weight units',['lb','kg'],S.user.units)}<p>Intended training days</p>${dayChecks(p.trainingDays)}<details><summary>Optional profile information</summary>${input('age','Age',p.age||'','number','min="13" max="110"')}${input('height','Height (include unit)',p.height||'')}${input('bodyWeight','Body weight (selected units)',p.bodyWeight||'','number','min="1" step="0.1"')}${input('limitations','Training preferences or limitations',p.limitations||'')}</details><button class="primary huge" type="submit">Save & choose a plan</button></form></div>`}
function planControls(){return `<section class="panel"><h2>Find your routine</h2><p class="muted">The Smith Method is the recommended four-day starter. Edits always create a private copy.</p><div class="featured-plans">${S.plans.filter(p=>p.is_template&&['The Smith Method','Cortez Compound'].includes(p.name)).map(p=>`<article class="featured-plan"><span class="eyebrow">${p.name==='The Smith Method'?'Recommended':'Featured'}</span><strong>${esc(p.name)}</strong><small>${p.days_per_week} days · ${esc(p.goal||'Strength & muscle')}</small></article>`).join('')}</div><label class="field">Choose a plan<select id="planChoice">${S.plans.map(p=>`<option value="${p.id}" ${p.id===S.plan?.id?'selected':''}>${esc(p.name)}${p.is_template?' · Template':' · Yours'}</option>`).join('')}</select></label><div class="row-actions"><button class="primary" data-extra="selectplan">Use selected plan</button><button class="secondary" data-extra="editplan">Clone & edit current</button></div><button class="secondary huge" data-extra="newplan">Create a custom plan</button></section>`}
function editorView(){const p=S.editor;return `<div class="screen">${header()}<h1>${S.adhoc?"Build today’s workout":"Build your plan"}</h1><p class="muted">Save creates a personal revision. Your past workouts stay intact.</p>${input('planName','Plan name',p.name,'text','id="editPlanName" maxlength="100"')}<div class="editor-days">${p.plan_days.map((d,di)=>`<section class="panel"><div class="mini-row"><label class="field">Day ${di+1} name<input data-dayname="${di}" value="${esc(d.name)}"></label><button class="dangerbtn" data-remove-day="${di}" aria-label="Remove day ${di+1}">Remove day</button></div>${d.plan_day_exercises.map((s,si)=>`<details class="editor-slot" open><summary>${si+1}. ${esc(s.exercises.name)}</summary><div class="editor-fields">${[['target_sets','Sets'],['min_reps','Min reps'],['max_reps','Max reps'],['target_rpe','RPE'],['rest_seconds','Rest seconds'],['duration_minutes','Minutes (timed)']].map(([k,l])=>`<label class="field">${l}<input data-slotfield="${di}:${si}:${k}" value="${esc(s[k]??(k==='duration_minutes'?0:''))}" inputmode="${k==='target_rpe'?'text':'numeric'}"></label>`).join('')}</div><div class="slot-actions"><button class="secondary" data-move-slot="${di}:${si}:-1" ${si===0?'disabled':''} aria-label="Move ${esc(s.exercises.name)} up">↑</button><button class="secondary" data-move-slot="${di}:${si}:1" ${si===d.plan_day_exercises.length-1?'disabled':''} aria-label="Move ${esc(s.exercises.name)} down">↓</button><button class="dangerbtn" data-remove-slot="${di}:${si}">Remove exercise</button></div></details>`).join('')}${builderPicker(di)}</section>`).join('')}</div><button class="secondary huge" data-extra="addday">Add training day</button><div class="row-actions"><button class="secondary" data-extra="canceledit">Cancel</button><button class="primary" data-extra="saveplan">${S.adhoc?"Start custom workout":"Save personal plan"}</button></div></div>`}
function builderCandidates(di){const f=S.builderFilters[di]||{},used=new Set(S.editor.plan_days[di].plan_day_exercises.map(x=>x.exercises.id));return searchExercises(f.query||'',f).filter(e=>!used.has(e.id))}
function builderPicker(di){const f=S.builderFilters[di]||{},list=builderCandidates(di);return `<div class="builder-picker"><h3>Add a movement</h3><label class="field">Search exercises<input data-builder-search="${di}" value="${esc(f.query||'')}" placeholder="Name, alias, muscle or equipment"></label>${catalogFilters(f,String(di))}<label class="check-label"><input type="checkbox" data-builder-favorites="${di}" ${f.favorites?'checked':''}> Favorites only</label><label class="field">Add exercise<select id="addExercise${di}">${list.map(e=>`<option value="${e.id}">${esc(e.name)} · ${esc(e.equipment)}</option>`).join('')}</select></label><p class="muted tiny" id="builderCount${di}">${list.length} matching movements</p><button class="secondary" data-add-exercise="${di}" ${list.length?'':'disabled'}>Add exercise</button></div>`}
function refreshBuilderPicker(di){const list=builderCandidates(di),select=document.getElementById('addExercise'+di);select.innerHTML=list.map(e=>`<option value="${e.id}">${esc(e.name)} · ${esc(e.equipment)}</option>`).join('');document.getElementById('builderCount'+di).textContent=list.length+' matching movements';document.querySelector(`[data-add-exercise="${di}"]`).disabled=!list.length;}

function supplementForm(){const s=S.suppEditor||{};return `<form id="suppForm" class="panel"><h2>${s.id?'Edit':'Add'} supplement</h2><p class="muted">Enter the dose you use. BodySmith does not recommend doses.</p>${input('name','Supplement name',s.name||'','text','list="suppNames" required maxlength="100"')}<datalist id="suppNames">${['Creatine','Protein powder','Magnesium','Zinc','Multivitamin','Turmeric','Omega-3','Vitamin D'].map(n=>`<option value="${n}">`).join('')}</datalist><div class="quick-grid">${input('dose','Your dose',s.dose||'')}${input('unit','Unit (g, mg, capsules…)',s.unit||'')}</div>${input('times','Times (24-hour, separated by commas)',(s.times||['09:00']).join(', '),'text','required placeholder="09:00, 18:00"')}<p>Scheduled days</p>${dayChecks(s.schedule_days||[0,1,2,3,4,5,6],'suppDays')}${input('with_food','With food note (optional)',s.with_food||'')}${input('notes','Personal notes',s.notes||'')}<label class="check-label"><input type="checkbox" name="active" ${s.active!==false?'checked':''}> Active</label><label class="check-label"><input type="checkbox" name="reminders" ${s.reminders?'checked':''}> Remind me at scheduled times</label><div class="row-actions"><button class="secondary" type="button" data-extra="cancelsupp">Cancel</button><button class="primary" type="submit">Save supplement</button></div></form>`}
function todayDoses(){const date=localDate();return S.supplements.filter(s=>s.active&&s.schedule_days.includes(new Date().getDay())).flatMap(s=>s.times.map(time=>({s,time,log:S.supplementLogs.find(l=>l.supplement_id===s.id&&l.scheduled_date===date&&l.scheduled_time===time)}))).sort((a,b)=>a.time.localeCompare(b.time))}
function supplementsView(){const doses=todayDoses(),taken=doses.filter(d=>d.log?.status==='taken').length;return shell(`<div class="section-title"><h1>Supplements</h1><span>${taken}/${doses.length} taken today</span></div>${S.suppEditor?supplementForm():`<button class="primary huge" data-extra="addsupp">Add supplement</button>`}<section class="panel"><h2>Today's checklist</h2>${doses.map(({s,time,log})=>`<article class="dose" data-status="${log?.status||'due'}"><div class="mini-row"><div><strong>${esc(s.name)}</strong><p class="muted">${esc(s.dose)} ${esc(s.unit)} · ${time}<br>${esc(s.with_food)}</p></div><span class="pill">${log?.status||'Due'}</span></div>${log?.status==='snoozed'?`<p class="muted">Snoozed until ${new Date(log.snoozed_until).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</p>`:''}<div class="dose-actions">${['taken','skipped','snoozed'].map(status=>`<button class="${status==='taken'?'primary':'secondary'}" data-dose="${s.id}|${time}|${status}">${status==='snoozed'?'Snooze 15m':status==='taken'?'Taken':'Skipped'}</button>`).join('')}</div></article>`).join('')||'<p class="muted">No supplements scheduled today.</p>'}</section><section class="panel"><h2>Your supplements</h2>${S.supplements.map(s=>`<div class="mini-row"><div><strong>${esc(s.name)}</strong><div class="muted">${s.active?'Active':'Inactive'} · ${s.times.join(', ')}</div></div><button class="secondary" data-editsupp="${s.id}">Edit</button></div>`).join('')||'<p class="muted">Add your first supplement above.</p>'}</section>${notificationPanel()}<section class="panel"><h2>Adherence history</h2><p class="muted">${S.supplementLogs.filter(l=>l.status==='taken').length} taken · ${S.supplementLogs.filter(l=>l.status==='skipped').length} skipped · last 90 days. Unlogged doses are not counted as taken.</p>${S.supplementLogs.slice().sort((a,b)=>(b.logged_at||'').localeCompare(a.logged_at||'')).slice(0,50).map(l=>`<div class="mini-row"><span>${esc(S.supplements.find(s=>s.id===l.supplement_id)?.name||'Supplement')}<br><small>${l.scheduled_date} ${l.scheduled_time}</small></span><strong>${l.status}</strong></div>`).join('')}</section>`)}
function notificationPanel(){const p=S.user.preferences||{},supported='Notification'in window&&'PushManager'in window&&'serviceWorker'in navigator,status=!supported?'Push unavailable in this browser. In-app reminders are available.':Notification.permission==='denied'?'Blocked in browser settings. In-app reminders remain available.':S.pushEnabled?'Push enabled on this device':Notification.permission==='granted'?'Permission granted; enable this device below.':'Not enabled. Choose when you want reminders.';return `<section class="panel"><h2>Reminders</h2><p class="muted" id="notificationStatus">${status}</p><label class="check-label"><input id="suppReminder" type="checkbox" ${p.supplementReminders?'checked':''}> Supplement reminders</label><label class="check-label"><input id="workoutReminder" type="checkbox" ${p.workoutReminders?'checked':''}> Planned workout days</label>${input('workoutTime','Workout reminder time',p.workoutTime||'17:00','time','id="workoutReminderTime"')}<p class="muted tiny">${esc(p.timezone||Intl.DateTimeFormat().resolvedOptions().timeZone)} · In-app reminders appear while BodySmith is open.</p><div class="row-actions"><button class="secondary" data-extra="savereminders">Save preferences</button><button class="primary" data-extra="enablepush" ${!supported||(typeof Notification!=='undefined'&&Notification.permission==='denied')?'disabled':''}>${S.pushEnabled?'Disable device push':'Enable notifications'}</button>${S.pushEnabled?'<button class="secondary" data-extra="testpush">Send test notification</button>':''}</div></section>`}
async function updatePreferences(p){const d=await api('update_profile',{displayName:S.user.display_name,units:S.user.units,preferences:{...S.user.preferences,...p}});S.user=d.user;persist()}
function sessionComparison(h){const previous=S.history.find(p=>p.status==='completed'&&p.id!==h.id&&new Date(p.started_at)<new Date(h.started_at)&&(p.plan_day_id===h.plan_day_id||(p.day_snapshot?.name&&p.day_snapshot.name===h.day_snapshot?.name)));if(!previous)return '<p class="muted">First workout for this day. This session becomes your comparison baseline.</p>';const volume=x=>(x.sets||[]).filter(s=>s.completion_status==='completed').reduce((v,s)=>v+(+s.weight||0)*(+s.reps||0)*(s.load_multiplier||1)*(s.units==='kg'?2.2046226218:1),0),before=volume(previous),after=volume(h),delta=before?Math.round((after-before)/before*100):null;return `<p>Last ${esc(h.day_snapshot?.name||'matching workout')}: ${new Date(previous.started_at).toLocaleDateString()}${delta==null?'':` · Load volume ${delta>=0?'+':''}${delta}%`}</p><p class="muted tiny">Compare sessions with similar exercise selections. More volume is not always the goal.</p>`;}

function sessionDetails(h){const sets=(h.sets||[]).filter(x=>x.completion_status==='completed'),volume=sets.reduce((a,x)=>a+(+x.weight||0)*(+x.reps||0)*(x.load_multiplier||1)*(x.units==='kg'?2.2046226218:1),0)/(S.user.units==='kg'?2.2046226218:1);return `<p><strong>${Math.round(volume).toLocaleString()} ${S.user.units}·reps</strong> logged load volume</p><p class="muted tiny">Load volume uses recorded load × reps × the recorded implement multiplier. Legacy records retain their original convention.</p>${sets.map(x=>{const e=allExercises().find(e=>e.id===x.exercise_id),rm=+x.reps>=1&&+x.reps<=10&&+x.weight>0&&/press|squat|deadlift|row/i.test(e?.name||'')?(+x.weight*(1+(+x.reps)/30)).toFixed(1):null;return `<div class="mini-row"><span>${esc(e?.name||'Exercise')} · set ${x.set_number}<br><small class="muted">${esc(x.notes||'')}</small></span><span>${x.duration_seconds?fmtDur(x.duration_seconds):`${x.weight??0} ${x.units||'lb'}${x.load_basis==='per_dumbbell'?' each':x.load_basis==='per_side'?' per side':''} × ${x.reps??0}`}<br><small class="muted">RPE ${x.rpe??'—'}${rm?` · est. 1RM ${rm} ${x.units||'lb'}`:''}</small></span></div>`}).join('')}<p class="muted tiny">Estimated 1RM uses the Epley formula for 1–10 reps on strength movements. It is a trend estimate, not a tested maximum.</p>`}
function progressMetrics(){const hs=S.history.filter(h=>h.status==='completed');const dates=new Set(hs.map(h=>localDate(new Date(h.started_at))));let streak=0,d=new Date();if(!dates.has(localDate(d)))d.setDate(d.getDate()-1);while(dates.has(localDate(d))){streak++;d.setDate(d.getDate()-1)}const week=new Date();week.setDate(week.getDate()-((week.getDay()+6)%7));week.setHours(0,0,0,0);return `<div class="stats-grid"><div class="stat"><span>This week / planned</span><strong>${hs.filter(h=>new Date(h.started_at)>=week).length} / ${S.user.preferences?.daysPerWeek||S.plan.days_per_week}</strong></div><div class="stat"><span>Consecutive training days</span><strong>${streak}</strong></div></div><p class="muted tiny">Rest days are expected. The streak counts consecutive calendar days trained.</p>`}
function checkinHistory(){return `<details class="panel"><summary>Daily check-in history</summary>${S.checkins.map(c=>`<div class="mini-row"><span>${c.checkin_date}</span><span>${c.body_weight??'—'} · pain ${c.elbow_pain??'—'}<br>${esc(c.notes||'')}</span></div>`).join('')||'<p class="muted">No check-ins yet.</p>'}</details>`}
function newSlot(e){const timed=['cardio','timed'].includes(e.exercise_type);return{exercises:e,exercise_id:e.id,target_sets:timed?1:3,min_reps:timed?0:8,max_reps:timed?0:12,target_rpe:e.exercise_type==='cardio'?'Easy':'7–8',rest_seconds:e.rest_min_seconds??90,duration_minutes:timed?(e.exercise_type==='cardio'?10:1):0}}
