 on('[data-favorite]',async el=>{const ids=new Set(S.user.preferences?.favorites||[]);ids.has(el.dataset.favorite)?ids.delete(el.dataset.favorite):ids.add(el.dataset.favorite);await updatePreferences({favorites:[...ids]});render()});
 const name=document.getElementById('editPlanName');if(name)name.oninput=()=>S.editor.name=name.value;
