async function togglePush(){const reg=await navigator.serviceWorker.ready,old=await reg.pushManager.getSubscription();if(old){await api('unsubscribe_push',{endpoint:old.endpoint});await old.unsubscribe();S.pushEnabled=false;toast('Push disabled on this device');return}const config=await api('notification_config');if(!config.configured)throw Error('Push setup is not ready. In-app reminders are available.');const permission=await Notification.requestPermission();if(permission!=='granted')throw Error('Notifications not enabled. In-app reminders remain available.');const raw=atob(config.publicKey.replace(/-/g,'+').replace(/_/g,'/')),key=Uint8Array.from(raw,c=>c.charCodeAt(0));const sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:key});try{await api('subscribe_push',{subscription:sub.toJSON()});S.pushEnabled=true;toast('Device notifications enabled')}catch(e){await sub.unsubscribe();throw e}}
let reminderShown=new Set();setInterval(()=>{if(!S.user)return;const p=S.user.preferences||{},now=new Date(),time=now.toTimeString().slice(0,5),key=localDate()+time;if(p.supplementReminders)for(const d of todayDoses()){const due=d.log?.status==='snoozed'?new Date(d.log.snoozed_until)<=now:!d.log&&d.time<=time,k=localDate()+d.s.id+d.time+(d.log?.snoozed_until||'');if(due&&d.s.reminders&&!reminderShown.has(k)){reminderShown.add(k);toast(`Supplement reminder: ${d.s.name}. Open Supplements to log it.`)}}if(p.workoutReminders&&p.trainingDays?.includes(now.getDay())&&p.workoutTime===time&&!reminderShown.has(key)){reminderShown.add(key);toast('Your planned workout is due. Ready when you are.')}},30000);

function loadSettings(ex){const units=S.user.units,p=S.user.preferences||{},saved=p.loading?.[units]||{},override=saved.exercises?.[ex?.id]||{};const equipment=ex?.equipment||'',kind=/dumbbell/i.test(equipment)?'dumbbell':/barbell|smith|trap.bar|EZ.bar/i.test(equipment)?'barbell':'machine';return {...saved,...override,kind,increment:+(saved[kind+'Increment'])||(units==='kg'?(kind==='dumbbell'?2:2.5):5),bar:override.bar??saved.bar??(units==='kg'?20:45),inventory:saved.inventory|| (units==='kg'?[25,20,15,10,5,2.5,1.25]:[45,35,25,10,5,2.5]).map(weight=>({weight,pairs:4})),basis:override.basis||ex?.load_basis||(/dumbbell/i.test(equipment)?'per_dumbbell':'total')};}
function plateEligible(ex){return /barbell|smith|plate.loaded|leg press|hack squat|T.bar|landmine|trap.bar|EZ.bar/i.test(ex.equipment||'')}
function weightLabel(ex){const basis=loadSettings(ex).basis;return basis==='per_dumbbell'?'per dumbbell':basis==='per_side'?'per side':'total'}
function nextSuggestion(slot){if(S.user.preferences?.smartProgression===false)return null;const ex=slot.exercise,settings=loadSettings(ex),known=settings.exercises?.[ex.id];if(!setsFor(ex.id).length&&!previousSets(ex.id).length&&!(+document.getElementById('weight')?.value>0))return null;return window.BodySmithTraining?.recommend({slot,exercise:ex,sets:setsFor(ex.id),previous:previousSets(ex.id),entered:+document.getElementById('weight')?.value||0,increment:settings.increment,plateConfig:plateEligible(ex)&&settings.basis==='total'&&(!/machine|smith|leg press/i.test(ex.equipment)||known?.bar!=null)?{bar:+settings.bar,inventory:settings.inventory}:null})}
function activeView(){let html=baseActiveView();const slot=dayExercises(S.activeDay)[S.activeIndex],ex=slot.exercise,rec=nextSuggestion(slot);const tools=`<details class="panel"><summary>Workout options</summary><button class="secondary huge" data-training="restart">Start Workout Over</button><button class="secondary huge" data-training="change">Change Workout</button><p class="muted tiny">Logged work is preserved as a partial session when you restart or change.</p></details>`;
 html=html.replace('<div class="session-strip">',tools+'<div class="session-strip">');
 html=html.replace('<div class="set-table">',`<p class="muted tiny">Weight: ${S.user.units} ${weightLabel(ex)}. Tap a logged set to correct it.</p>${plateEligible(ex)?'<button class="secondary" data-training="plates">Calculate Plates</button>':''}<div class="set-table">`);
 html=html.replace('<div class="row-actions"><button class="secondary" data-action="prevexercise">',`<div class="row-actions"><button class="secondary" data-training="extra">+ Add Set</button>${slot.target_sets>(slot.programmed_sets||slot.target_sets)?'<button class="secondary" data-training="removeextra">Remove extra target</button>':''}</div>${rec&&setsFor(ex.id).length<slot.target_sets?`<section class="panel"><strong>${rec.starting?'Suggested starting load':'Suggested next set'}</strong><p>${rec.weight} ${S.user.units} ${weightLabel(ex)} × ${rec.minReps}${rec.maxReps!==rec.minReps?'–'+rec.maxReps:''}</p><p class="muted tiny">${esc(rec.reason)}</p><button class="secondary" data-training="suggest">Use Suggestion</button> <button class="secondary" data-training="keep">Keep Previous</button></section>`:''}<div class="row-actions"><button class="secondary" data-action="prevexercise">`);return html;}
function openSetEditor(session,exerciseId,number){const old=(session.sets||[]).find(x=>x.exercise_id===exerciseId&&x.set_number===number)||{},ex=allExercises().find(x=>x.id===exerciseId)||{},units=old.units||S.user.units;app.insertAdjacentHTML('beforeend',`<dialog open class="custom-dialog" aria-label="Edit set"><form id="setEditForm"><h2>${old.id?'Edit':'Add'} set ${number}</h2><p>${esc(ex.name)} · ${units} ${old.load_basis||weightLabel(ex)}</p>${[['weight','Weight',old.weight],['reps','Reps',old.reps],['rpe','RPE',old.rpe],['elbow_pain','Pain 0–10',old.elbow_pain],['duration_seconds','Duration seconds (timed)',old.duration_seconds]].map(([k,label,val])=>`<label class="field">${label}<input name="${k}" inputmode="decimal" value="${val??''}"></label>`).join('')}<label class="field">Notes<textarea name="notes">${esc(old.notes||'')}</textarea></label><label class="field">Status<select name="completion_status"><option value="completed">Completed</option><option value="skipped" ${old.completion_status==='skipped'?'selected':''}>Skipped</option></select></label><button class="primary huge">Save set</button>${old.id?'<button type="button" class="dangerbtn huge" id="deleteSet">Delete erroneous set</button>':''}<button type="button" class="secondary huge" id="cancelSet">Cancel</button></form></dialog>`);
 document.getElementById('cancelSet').onclick=()=>render();
 const remove=document.getElementById('deleteSet');if(remove)remove.onclick=async()=>{if(!confirm('Delete this erroneous set? This removes it from workout metrics and history.'))return;session.sets=session.sets.filter(x=>!(x.exercise_id===exerciseId&&x.set_number===number));queue('delete_set',{sessionId:session.id,exerciseId,setNumber:number});persist();render();await syncQueue()};
 document.getElementById('setEditForm').onsubmit=async ev=>{ev.preventDefault();const f=Object.fromEntries(new FormData(ev.target)),numberOrNull=k=>f[k]===''?null:Number(f[k]);const vals={weight:numberOrNull('weight'),reps:numberOrNull('reps'),rpe:numberOrNull('rpe'),elbow_pain:numberOrNull('elbow_pain'),duration_seconds:numberOrNull('duration_seconds')};if(Object.values(vals).some(x=>x!=null&&!Number.isFinite(x))||vals.weight<0||vals.reps<0||(vals.reps!=null&&!Number.isInteger(vals.reps))||(vals.rpe!=null&&(vals.rpe<1||vals.rpe>10))||vals.elbow_pain<0||vals.elbow_pain>10||vals.duration_seconds<0){toast('Check weight, reps, RPE, pain and duration.',true);return}
 const row={...old,...vals,id:old.id||crypto.randomUUID(),exercise_id:exerciseId,set_number:number,units,notes:String(f.notes).slice(0,500),completion_status:f.completion_status,updated_at:new Date().toISOString(),logged_at:old.logged_at||session.started_at,load_basis:old.load_basis||loadSettings(ex).basis,load_multiplier:old.load_multiplier??((loadSettings(ex).basis==='per_side'||loadSettings(ex).basis==='per_dumbbell'&&ex.laterality==='Bilateral')?2:1)};session.sets=[...(session.sets||[]).filter(x=>!(x.exercise_id===exerciseId&&x.set_number===number)),row].sort((a,b)=>a.set_number-b.set_number);queue('save_set',{sessionId:session.id,exerciseId,setNumber:number,units,weight:row.weight,reps:row.reps,rpe:row.rpe,elbowPain:row.elbow_pain,durationSeconds:row.duration_seconds,notes:row.notes,completionStatus:row.completion_status,loadBasis:row.load_basis,loadMultiplier:row.load_multiplier});persist();render();await syncQueue();toast('Set corrected. Metrics and suggestions recalculated.');};}
function historyEditorView(){const h=S.history.find(x=>x.id===S.editHistory);if(!h){S.editHistory=null;return home()}const day=h.day_snapshot||dayById(h.plan_day_id);return `<div class="screen">${header()}<h1>Edit Workout</h1><p>${esc(day?.name||'Workout')} · ${new Date(h.started_at).toLocaleString()}</p><p class="muted">Corrections keep the original workout date.</p>${dayExercises(day).map(slot=>`<section class="panel"><h3>${esc(slot.exercise.name)}</h3>${(h.sets||[]).filter(x=>x.exercise_id===slot.exercise.id).map(x=>`<button class="secondary huge" data-history-set="${slot.exercise.id}:${x.set_number}">Set ${x.set_number}: ${x.weight??0} ${x.units||'lb'}${x.load_basis==='per_dumbbell'?' each':x.load_basis==='per_side'?' per side':''} × ${x.reps??0} · ${esc(x.completion_status)} · Edit</button>`).join('')}<button class="secondary" data-history-add="${slot.exercise.id}">+ Add missing set</button></section>`).join('')}<label class="field">Workout notes<textarea id="historyNotes">${esc(h.workout_notes||'')}</textarea></label><button class="primary huge" data-training="historydone">Save notes & close</button></div>`}
async function changeWorkout(restart){if(!confirm(restart?'Restart from set 1? Existing work will stay in History as partial.':'Leave this workout? Logged work will stay in History as partial.'))return;const old=S.active,day=structuredClone(S.activeDay);old.status='abandoned';old.completed_at=new Date().toISOString();old.day_snapshot=day;S.history=[old,...S.history.filter(x=>x.id!==old.id)];queue('abandon_session',{sessionId:old.id,completedAt:old.completed_at,notes:restart?'Restarted workout':'Changed workout'});S.active=null;S.activeDay=null;S.screen='workout';setRest(0);persist();render();await syncQueue();if(restart&&!getQueue().length){if(day.id)await startWorkout(day.id);else await startCustomDay(day)}else if(restart)toast('Partial workout saved on this device. Connect and sync before restarting.');}
async function startCustomDay(day){if(!S.online)throw Error('Connect to start a new workout.');const r=await api('start_custom_session',{day});S.active=r.session;S.activeDay=structuredClone(r.session.day_snapshot);S.activeIndex=0;S.editor=null;S.adhoc=false;S.screen='active';persist();cacheWorkoutMedia();render()}
function plateDialog(){const ex=dayExercises(S.activeDay)[S.activeIndex].exercise,cfg=loadSettings(ex),machine=/machine|smith|leg press|hack squat/i.test(ex.equipment),known=cfg.exercises?.[ex.id]?.bar;app.insertAdjacentHTML('beforeend',`<dialog open class="custom-dialog"><h2>Plate Calculator</h2><p>Balanced plates on each side · ${S.user.units}</p><label class="field">Desired total loaded weight<input id="plateTotal" inputmode="decimal" value="${document.getElementById('weight')?.value||''}"></label><label class="field">${machine?'Machine base/start weight (enter known resistance, or 0 for added plates only)':'Bar weight'}<input id="plateBar" inputmode="decimal" value="${machine?(known??''):cfg.bar}"></label><p class="muted tiny">Plate inventory is configured in Profile. ${cfg.basis==='per_side'?'Applying a total fills half the added plate load into your per-side entry.':''}</p><label class="field">Set weight convention<select id="plateBasis"><option value="total">Total loaded weight</option><option value="per_side" ${cfg.basis==='per_side'?'selected':''}>Added plates per side</option></select></label><button class="secondary huge" id="saveExerciseBase">Save base & convention for this exercise</button><div id="plateResult" aria-live="polite"></div><button class="secondary huge" id="closePlates">Close</button></dialog>`);
 const calculate=()=>{const target=document.getElementById('plateTotal').value,base=document.getElementById('plateBar').value,result=document.getElementById('plateResult');if(target===''||base===''){result.textContent='Enter the total and bar/base weight. Machine resistance is never assumed.';return}try{const r=window.BodySmithTraining.plateLoads(+target,+base,cfg.inventory);result.innerHTML=(r.exact?'':'<h3>Exact load unavailable</h3>')+[r.exact||r.lower,...(r.exact?[]:[r.higher])].filter(Boolean).map(x=>`<section class="panel"><strong>${x.total} ${S.user.units} total</strong><p>Bar/base: ${x.bar} ${S.user.units}</p><p><b>Each side: ${x.perSide} ${S.user.units}</b></p><p>Left: ${x.plates.join(' + ')||'No plates'}<br>Right: ${x.plates.join(' + ')||'No plates'}</p><button class="primary" data-apply-plates="${x.total}">Use ${x.total} ${S.user.units} total</button></section>`).join('');result.querySelectorAll('[data-apply-plates]').forEach(b=>b.onclick=()=>{const val=cfg.basis==='per_side'?(+b.dataset.applyPlates-(+base))/2:+b.dataset.applyPlates;const w=document.getElementById('weight');if(w)w.value=val;b.closest('dialog').remove()});}catch(e){result.textContent=e.message}};document.getElementById('saveExerciseBase').onclick=async()=>{try{const v=document.getElementById('plateBar').value;if(v===''||!Number.isFinite(+v)||+v<0)throw Error('Enter a known base, or 0 for added plates only.');const p=S.user.preferences||{},all=p.loading||{},unit=all[S.user.units]||{};await updatePreferences({loading:{...all,[S.user.units]:{...unit,exercises:{...unit.exercises,[ex.id]:{bar:+v,basis:document.getElementById('plateBasis').value}}}}});toast('Exercise loading settings saved');document.querySelector('dialog').remove();render()}catch(e){toast(e.message,true)}};document.getElementById('plateTotal').oninput=calculate;document.getElementById('plateBar').oninput=calculate;document.getElementById('closePlates').onclick=()=>document.querySelector('dialog').remove();calculate();}
function loadingSettingsView(){const cfg=loadSettings(),p=S.user.preferences||{};return `<details class="panel"><summary>Smart Progression & loading settings</summary><form id="loadingSettings"><label class="check-label"><input name="smart" type="checkbox" ${p.smartProgression!==false?'checked':''}> Smart Progression</label><p class="muted tiny">Suggestions are optional. Settings below apply to ${S.user.units}.</p>${[['bar','Default bar weight',cfg.bar],['barbellIncrement','Barbell total increment',cfg.barbellIncrement||(S.user.units==='kg'?2.5:5)],['dumbbellIncrement','Dumbbell increment per hand',cfg.dumbbellIncrement||(S.user.units==='kg'?2:5)],['machineIncrement','Machine/stack increment',cfg.machineIncrement||5]].map(([key,label,val])=>`<label class="field">${label}<input name="${key}" value="${val}" inputmode="decimal"></label>`).join('')}<label class="field">Plate inventory: weight × pairs, comma separated<textarea name="inventory">${cfg.inventory.map(p=>p.weight+'x'+p.pairs).join(', ')}</textarea></label><p class="muted tiny">Example: 45x2 means two pairs of 45 lb plates. Default bar may be 45 lb, 35 lb, 15 kg, 20 kg, or custom.</p><button class="primary huge">Save loading settings</button></form></details>`}
function bindTraining(){const on=(sel,fn)=>document.querySelectorAll(sel).forEach(el=>el.onclick=async()=>{try{await fn(el)}catch(e){toast(e.message,true)}});on('[data-edit-set]',el=>{const [ex,n]=el.dataset.editSet.split(':');openSetEditor(S.active,ex,+n)});on('[data-history-edit]',el=>{S.editHistory=el.dataset.historyEdit;render()});on('[data-history-set]',el=>{const [ex,n]=el.dataset.historySet.split(':');openSetEditor(S.history.find(x=>x.id===S.editHistory),ex,+n)});on('[data-history-add]',el=>{const h=S.history.find(x=>x.id===S.editHistory),id=el.dataset.historyAdd,n=Math.max(0,...h.sets.filter(x=>x.exercise_id===id).map(x=>x.set_number))+1;if(n>20)throw Error('Maximum 20 sets per exercise.');openSetEditor(h,id,n)});
 on('[data-training]',async el=>{const action=el.dataset.training,slot=S.activeDay?dayExercises(S.activeDay)[S.activeIndex]:null;switch(action){case 'extra':{const base=S.activeDay.plan_day_exercises.find(x=>x.id===slot.id);if(base.target_sets>=20)throw Error('Maximum 20 sets per exercise.');base.programmed_sets??=base.target_sets;base.target_sets++;queue('set_targets',{sessionId:S.active.id,slotId:slot.id,targetSets:base.target_sets});persist();render();await syncQueue();break;}case 'removeextra':{const base=S.activeDay.plan_day_exercises.find(x=>x.id===slot.id);if(setsFor(slot.exercise.id).some(x=>x.set_number===base.target_sets))throw Error('Edit or delete the logged extra set first.');base.target_sets--;queue('set_targets',{sessionId:S.active.id,slotId:slot.id,targetSets:base.target_sets});persist();render();await syncQueue();break;}case 'suggest':{const r=nextSuggestion(slot);if(r&&document.getElementById('weight')){document.getElementById('weight').value=r.weight;document.getElementById('reps').value=r.minReps;}break;}case 'keep':{const last=setsFor(slot.exercise.id).filter(x=>x.completion_status==='completed').at(-1)||previousSets(slot.exercise.id)[0];if(last&&document.getElementById('weight')){document.getElementById('weight').value=last.weight??'';document.getElementById('reps').value=last.reps??slot.min_reps}break;}case 'plates':plateDialog();break;case 'restart':await changeWorkout(true);break;case 'change':await changeWorkout(false);break;case 'custom':if(S.active)throw Error('Use Change Workout before starting another.');S.adhoc=true;S.builderFilters={};S.editor={name:'Today’s custom workout',plan_days:[{name:'Custom Workout',plan_day_exercises:[]}]};render();break;case 'historydone':{const h=S.history.find(x=>x.id===S.editHistory);h.workout_notes=document.getElementById('historyNotes').value;queue('session_notes',{sessionId:h.id,notes:h.workout_notes});S.editHistory=null;persist();render();await syncQueue();break;}}});
 document.querySelectorAll('[data-edit-set]').forEach(el=>el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();el.click()}});const form=document.getElementById('loadingSettings');if(form)form.onsubmit=async ev=>{ev.preventDefault();try{const f=new FormData(form),cfg={};for(const key of ['bar','barbellIncrement','dumbbellIncrement','machineIncrement']){cfg[key]=+f.get(key);if(!Number.isFinite(cfg[key])||cfg[key]<(key==='bar'?0:.1)||cfg[key]>1000)throw Error('Enter valid bar weight and positive increments.')}cfg.inventory=String(f.get('inventory')).split(',').map(t=>{const [weight,pairs]=t.trim().split(/x|×/).map(Number);if(!(weight>0)||weight>100||!Number.isInteger(pairs)||pairs<1||pairs>20)throw Error('Inventory format: 45x2, 25x2. Use 1–20 pairs.');return {weight,pairs}});const loading={...S.user.preferences?.loading,[S.user.units]:{...S.user.preferences?.loading?.[S.user.units],...cfg}};await updatePreferences({smartProgression:f.has('smart'),loading});toast('Loading preferences saved');render()}catch(e){toast(e.message,true)}};
}


function home(){const completed=S.history.filter(h=>h.status==='completed'),week=new Date();week.setDate(week.getDate()-((week.getDay()+6)%7));week.setHours(0,0,0,0);const recent=completed.filter(h=>new Date(h.started_at)>=week),count=recent.flatMap(h=>h.sets||[]).filter(s=>s.completion_status==='completed').length;const intro=`<section class="dashboard-intro"><h1>Ready, ${esc(S.user.display_name||'athlete')}?</h1><p>Progress is a habit. Make today count.</p><div class="stats-grid dashboard-stats"><div class="stat"><span>Workouts this week</span><strong>${recent.length} / ${S.user.preferences?.daysPerWeek||S.plan?.days_per_week||4}</strong></div><div class="stat"><span>Sets this week</span><strong>${count}</strong></div></div></section>`;return baseHome().replace('<section class="card plan-banner">',intro+'<section class="card plan-banner">').replace('<nav class="bottom-nav" aria-label="Primary navigation">','<button class="secondary huge" data-training="custom">Start Custom Workout</button><nav class="bottom-nav" aria-label="Primary navigation">')}

bootstrap();
